    AccountRecoverySettingType.add_member(:recovery_mechanisms, Smithy::Schema::Shapes::ShapeRef.new(shape: RecoveryMechanismsType, location_name: 'RecoveryMechanisms', traits: {"smithy.api#documentation" => "<p>The list of options and priorities for user message delivery in forgot-password\n            operations. Sets or displays user pool preferences for email or SMS message priority,\n            whether users should fall back to a second delivery method, and whether passwords should\n            only be reset by administrators.</p>"}))
    AccountRecoverySettingType.type = Types::AccountRecoverySettingType
    AccountTakeoverActionType.add_member(:notify, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverActionNotifyType, location_name: 'Notify', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Determines whether Amazon Cognito sends a user a notification message when your user pools\n            assesses a user's session at the associated risk level.</p>", "smithy.api#required" => {}}))
    AccountTakeoverActionType.add_member(:event_action, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverEventActionType, location_name: 'EventAction', traits: {"smithy.api#documentation" => "<p>The action to take for the attempted account takeover action for the associated risk\n            level. Valid values are as follows:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>BLOCK</code>: Block the request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MFA_IF_CONFIGURED</code>: Present an MFA challenge if possible. MFA is\n                    possible if the user pool has active MFA methods that the user can set up. For\n                    example, if the user pool only supports SMS message MFA but the user\n                    doesn't have a phone number attribute, MFA setup isn't possible. If MFA\n                    setup isn't possible, allow the request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MFA_REQUIRED</code>: Present an MFA challenge if possible. Block the\n                    request if a user hasn't set up MFA. To sign in with required MFA, users must\n                    have an email address or phone number attribute, or a registered TOTP\n                    factor.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NO_ACTION</code>: Take no action. Permit sign-in.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    AccountTakeoverActionType.type = Types::AccountTakeoverActionType
    AccountTakeoverActionsType.add_member(:low_action, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverActionType, location_name: 'LowAction', traits: {"smithy.api#documentation" => "<p>The action that you assign to a low-risk assessment by threat protection.</p>"}))
    AccountTakeoverActionsType.add_member(:medium_action, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverActionType, location_name: 'MediumAction', traits: {"smithy.api#documentation" => "<p>The action that you assign to a medium-risk assessment by threat protection.</p>"}))
    AccountTakeoverActionsType.add_member(:high_action, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverActionType, location_name: 'HighAction', traits: {"smithy.api#documentation" => "<p>The action that you assign to a high-risk assessment by threat protection.</p>"}))
    AccountTakeoverActionsType.type = Types::AccountTakeoverActionsType
    AccountTakeoverEventActionType.add_member(:block, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BLOCK', traits: {"smithy.api#enumValue" => "BLOCK"}))
    AccountTakeoverEventActionType.add_member(:mfa_if_configured, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MFA_IF_CONFIGURED', traits: {"smithy.api#enumValue" => "MFA_IF_CONFIGURED"}))
    AccountTakeoverEventActionType.add_member(:mfa_required, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MFA_REQUIRED', traits: {"smithy.api#enumValue" => "MFA_REQUIRED"}))
    AccountTakeoverEventActionType.add_member(:no_action, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NO_ACTION', traits: {"smithy.api#enumValue" => "NO_ACTION"}))
    AccountTakeoverRiskConfigurationType.add_member(:notify_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NotifyConfigurationType, location_name: 'NotifyConfiguration', traits: {"smithy.api#documentation" => "<p>The settings for composing and sending an email message when threat protection\n            assesses a risk level with adaptive authentication. When you choose to notify users in\n                <code>AccountTakeoverRiskConfiguration</code>, Amazon Cognito sends an email message using\n            the method and template that you set with this data type.</p>"}))
    AccountTakeoverRiskConfigurationType.add_member(:actions, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverActionsType, location_name: 'Actions', traits: {"smithy.api#documentation" => "<p>A list of account-takeover actions for each level of risk that Amazon Cognito might assess with\n            threat protection.</p>", "smithy.api#required" => {}}))
    AccountTakeoverRiskConfigurationType.type = Types::AccountTakeoverRiskConfigurationType
    AddCustomAttributesRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to add custom attributes.</p>", "smithy.api#required" => {}}))
    AddCustomAttributesRequest.add_member(:custom_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomAttributesListType, location_name: 'CustomAttributes', traits: {"smithy.api#documentation" => "<p>An array of custom attribute names and other properties. Sets the following\n            characteristics:</p>\n         <dl>\n            <dt>AttributeDataType</dt>\n            <dd>\n               <p>The expected data type. Can be a string, a number, a date and time, or a\n                        boolean.</p>\n            </dd>\n            <dt>Mutable</dt>\n            <dd>\n               <p>If true, you can grant app clients write access to the attribute value. If\n                        false, the attribute value can only be set up on sign-up or administrator\n                        creation of users.</p>\n            </dd>\n            <dt>Name</dt>\n            <dd>\n               <p>The attribute name. For an attribute like <code>custom:myAttribute</code>,\n                        enter <code>myAttribute</code> for this field.</p>\n            </dd>\n            <dt>Required</dt>\n            <dd>\n               <p>When true, users who sign up or are created must set a value for the\n                        attribute.</p>\n            </dd>\n            <dt>NumberAttributeConstraints</dt>\n            <dd>\n               <p>The minimum and maximum length of accepted values for a\n                            <code>Number</code>-type attribute.</p>\n            </dd>\n            <dt>StringAttributeConstraints</dt>\n            <dd>\n               <p>The minimum and maximum length of accepted values for a\n                            <code>String</code>-type attribute.</p>\n            </dd>\n            <dt>DeveloperOnlyAttribute</dt>\n            <dd>\n               <p>This legacy option creates an attribute with a <code>dev:</code> prefix.\n                        You can only set the value of a developer-only attribute with administrative\n                        IAM credentials.</p>\n            </dd>\n         </dl>", "smithy.api#required" => {}}))
    AddCustomAttributesRequest.type = Types::AddCustomAttributesRequest
    AddCustomAttributesResponse.type = Types::AddCustomAttributesResponse
    AdminAddUserToGroupRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool that contains the group that you want to add the user\n            to.</p>", "smithy.api#required" => {}}))
    AdminAddUserToGroupRequest.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameType, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The name of the user that you want to query or modify. The value of this parameter\n            is typically your user's username, but it can be any of their alias attributes. If\n                <code>username</code> isn't an alias attribute in your user pool, this value\n            must be the <code>sub</code> of a local user or the username of a user from a\n            third-party IdP.</p>", "smithy.api#required" => {}}))
    AdminAddUserToGroupRequest.add_member(:group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupNameType, location_name: 'GroupName', traits: {"smithy.api#documentation" => "<p>The name of the group that you want to add your user to.</p>", "smithy.api#required" => {}}))
    AdminAddUserToGroupRequest.type = Types::AdminAddUserToGroupRequest
    AdminConfirmSignUpRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to confirm a user's sign-up\n            request.</p>", "smithy.api#required" => {}}))
    AdminConfirmSignUpRequest.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameType, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The name of the user that you want to query or modify. The value of this parameter\n            is typically your user's username, but it can be any of their alias attributes. If\n                <code>username</code> isn't an alias attribute in your user pool, this value\n            must be the <code>sub</code> of a local user or the username of a user from a\n            third-party IdP.</p>", "smithy.api#required" => {}}))
    AdminConfirmSignUpRequest.add_member(:client_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientMetadataType, location_name: 'ClientMetadata', traits: {"smithy.api#documentation" => "<p>A map of custom key-value pairs that you can provide as input for any custom workflows\n            that this action triggers.</p>\n         <p>If your user pool configuration includes triggers, the AdminConfirmSignUp API action\n            invokes the Lambda function that is specified for the <i>post\n                confirmation</i> trigger. When Amazon Cognito invokes this function, it passes a JSON\n            payload, which the function receives as input. In this payload, the\n                <code>clientMetadata</code> attribute provides the data that you assigned to the\n            ClientMetadata parameter in your AdminConfirmSignUp request. In your function code in\n            Lambda, you can process the ClientMetadata value to enhance your workflow for your\n            specific needs.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-identity-pools-working-with-aws-lambda-triggers.html\">\nUsing Lambda triggers</a> in the <i>Amazon Cognito Developer Guide</i>.</p>\n         <note>\n            <p>When you use the <code>ClientMetadata</code> parameter, note that Amazon Cognito won't do the\n                following:</p>\n            <ul>\n               <li>\n                  <p>Store the <code>ClientMetadata</code> value. This data is available only\n                        to Lambda triggers that are assigned to a user pool to support custom\n                        workflows. If your user pool configuration doesn't include triggers, the\n                        <code>ClientMetadata</code> parameter serves no purpose.</p>\n               </li>\n               <li>\n                  <p>Validate the <code>ClientMetadata</code> value.</p>\n               </li>\n               <li>\n                  <p>Encrypt the <code>ClientMetadata</code> value. Don't send sensitive\n                        information in this parameter.</p>\n               </li>\n            </ul>\n         </note>"}))
    AdminConfirmSignUpRequest.type = Types::AdminConfirmSignUpRequest
    AdminConfirmSignUpResponse.type = Types::AdminConfirmSignUpResponse
    AdminCreateUserConfigType.add_member(:allow_admin_create_user_only, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'AllowAdminCreateUserOnly', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>The setting for allowing self-service sign-up. When <code>true</code>, only\n            administrators can create new user profiles. When <code>false</code>, users can register\n            themselves and create a new user profile with the <code>SignUp</code> operation.</p>"}))
    AdminCreateUserConfigType.add_member(:unused_account_validity_days, Smithy::Schema::Shapes::ShapeRef.new(shape: AdminCreateUserUnusedAccountValidityDaysType, location_name: 'UnusedAccountValidityDays', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>This parameter is no longer in use.</p>\n         <p>The password expiration limit in days for administrator-created users. When this time\n            expires, the user can't sign in with their temporary password. To reset the account\n            after that time limit, you must call <code>AdminCreateUser</code> again, specifying\n                <code>RESEND</code> for the <code>MessageAction</code> parameter. </p>\n         <p>The default value for this parameter is 7.</p>"}))
    AdminCreateUserConfigType.add_member(:invite_message_template, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageTemplateType, location_name: 'InviteMessageTemplate', traits: {"smithy.api#documentation" => "<p>The template for the welcome message to new users. This template must include the\n                <code>{####}</code> temporary password placeholder if you are creating users with\n            passwords. If your users don't have passwords, you can omit the placeholder.</p>\n         <p>See also <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pool-settings-message-customizations.html#cognito-user-pool-settings-user-invitation-message-customization\">Customizing User Invitation Messages</a>.</p>"}))
    AdminCreateUserConfigType.type = Types::AdminCreateUserConfigType
    AdminCreateUserRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to create a user.</p>", "smithy.api#required" => {}}))
    AdminCreateUserRequest.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameType, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The value that you want to set as the username sign-in attribute. The following\n            conditions apply to the username parameter.</p>\n         <ul>\n            <li>\n               <p>The username can't be a duplicate of another username in the same user\n                    pool.</p>\n            </li>\n            <li>\n               <p>You can't change the value of a username after you create it.</p>\n            </li>\n            <li>\n               <p>You can only provide a value if usernames are a valid sign-in attribute for\n                    your user pool. If your user pool only supports phone numbers or email addresses\n                    as sign-in attributes, Amazon Cognito automatically generates a username value. For more\n                    information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-settings-attributes.html#user-pool-settings-aliases\">Customizing sign-in attributes</a>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    AdminCreateUserRequest.add_member(:user_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeListType, location_name: 'UserAttributes', traits: {"smithy.api#documentation" => "<p>An array of name-value pairs that contain user attributes and attribute values to be\n            set for the user to be created. You can create a user without specifying any attributes\n            other than <code>Username</code>. However, any attributes that you specify as required\n            (when creating a user pool or in the <b>Attributes</b> tab of\n            the console) either you should supply (in your call to <code>AdminCreateUser</code>) or\n            the user should supply (when they sign up in response to your welcome message).</p>\n         <p>For custom attributes, you must prepend the <code>custom:</code> prefix to the\n            attribute name.</p>\n         <p>To send a message inviting the user to sign up, you must specify the user's email\n            address or phone number. You can do this in your call to AdminCreateUser or in the\n                <b>Users</b> tab of the Amazon Cognito console for managing your\n            user pools.</p>\n         <p>You must also provide an email address or phone number when you expect the user to do\n            passwordless sign-in with an email or SMS OTP. These attributes must be provided when\n            passwordless options are the only available, or when you don't submit a\n                <code>TemporaryPassword</code>.</p>\n         <p>In your <code>AdminCreateUser</code> request, you can set the\n                <code>email_verified</code> and <code>phone_number_verified</code> attributes to\n                <code>true</code>. The following conditions apply:</p>\n         <dl>\n            <dt>email</dt>\n            <dd>\n               <p>The email address where you want the user to receive their confirmation\n                        code and username. You must provide a value for <code>email</code> when you\n                        want to set <code>email_verified</code> to <code>true</code>, or if you set\n                            <code>EMAIL</code> in the <code>DesiredDeliveryMediums</code>\n                        parameter.</p>\n            </dd>\n            <dt>phone_number</dt>\n            <dd>\n               <p>The phone number where you want the user to receive their confirmation\n                        code and username. You must provide a value for <code>phone_number</code>\n                        when you want to set <code>phone_number_verified</code> to\n                        <code>true</code>, or if you set <code>SMS</code> in the\n                            <code>DesiredDeliveryMediums</code> parameter.</p>\n            </dd>\n         </dl>"}))
    AdminCreateUserRequest.add_member(:validation_data, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeListType, location_name: 'ValidationData', traits: {"smithy.api#documentation" => "<p>Temporary user attributes that contribute to the outcomes of your pre sign-up Lambda\n    trigger. This set of key-value pairs are for custom validation of information that you \n    collect from your users but don't need to retain.</p>\n         <p>Your Lambda function can analyze this additional data and act on it. Your function\n    can automatically confirm and verify select users or perform external API operations \n    like logging user attributes and validation data to Amazon CloudWatch Logs.</p>\n         <p>For more information about the pre sign-up Lambda trigger, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-lambda-pre-sign-up.html\">Pre sign-up Lambda trigger</a>.</p>"}))
    AdminCreateUserRequest.add_member(:temporary_password, Smithy::Schema::Shapes::ShapeRef.new(shape: PasswordType, location_name: 'TemporaryPassword', traits: {"smithy.api#documentation" => "<p>The user's temporary password. This password must conform to the password policy that\n            you specified when you created the user pool.</p>\n         <p>The exception to the requirement for a password is when your user pool supports\n            passwordless sign-in with email or SMS OTPs. To create a user with no password, omit\n            this parameter or submit a blank value. You can only create a passwordless user when\n            passwordless sign-in is available.</p>\n         <p>The temporary password is valid only once. To complete the Admin Create User flow, the\n            user must enter the temporary password in the sign-in page, along with a new password to\n            be used in all future sign-ins.</p>\n         <p>If you don't specify a value, Amazon Cognito generates one for you unless you have passwordless\n            options active for your user pool.</p>\n         <p>The temporary password can only be used until the user account expiration limit that\n            you set for your user pool. To reset the account after that time limit, you must call\n                <code>AdminCreateUser</code> again and specify <code>RESEND</code> for the\n                <code>MessageAction</code> parameter.</p>"}))
    AdminCreateUserRequest.add_member(:force_alias_creation, Smithy::Schema::Shapes::ShapeRef.new(shape: ForceAliasCreation, location_name: 'ForceAliasCreation', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>This parameter is used only if the <code>phone_number_verified</code> or\n                <code>email_verified</code> attribute is set to <code>True</code>. Otherwise, it is\n            ignored.</p>\n         <p>If this parameter is set to <code>True</code> and the phone number or email address\n            specified in the <code>UserAttributes</code> parameter already exists as an alias with a\n            different user, this request migrates the alias from the previous user to the\n            newly-created user. The previous user will no longer be able to log in using that\n            alias.</p>\n         <p>If this parameter is set to <code>False</code>, the API throws an\n                <code>AliasExistsException</code> error if the alias already exists. The default\n            value is <code>False</code>.</p>"}))
    AdminCreateUserRequest.add_member(:message_action, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageActionType, location_name: 'MessageAction', traits: {"smithy.api#documentation" => "<p>Set to <code>RESEND</code> to resend the invitation message to a user that already\n            exists, and to reset the temporary-password duration with a new temporary password. Set\n            to <code>SUPPRESS</code> to suppress sending the message. You can specify only one\n            value.</p>"}))
    AdminCreateUserRequest.add_member(:desired_delivery_mediums, Smithy::Schema::Shapes::ShapeRef.new(shape: DeliveryMediumListType, location_name: 'DesiredDeliveryMediums', traits: {"smithy.api#documentation" => "<p>Specify <code>EMAIL</code> if email will be used to send the welcome message. Specify\n                <code>SMS</code> if the phone number will be used. The default value is\n                <code>SMS</code>. You can specify more than one value.</p>"}))
    AdminCreateUserRequest.add_member(:client_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientMetadataType, location_name: 'ClientMetadata', traits: {"smithy.api#documentation" => "<p>A map of custom key-value pairs that you can provide as input for any custom workflows\n            that this action triggers.</p>\n         <p>You create custom workflows by assigning Lambda functions to user pool triggers.\n            When you use the AdminCreateUser API action, Amazon Cognito invokes the function that is assigned\n            to the <i>pre sign-up</i> trigger. When Amazon Cognito invokes this function, it\n            passes a JSON payload, which the function receives as input. This payload contains a\n                <code>ClientMetadata</code> attribute, which provides the data that you assigned to\n            the ClientMetadata parameter in your AdminCreateUser request. In your function code in\n            Lambda, you can process the <code>clientMetadata</code> value to enhance your\n            workflow for your specific needs.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-identity-pools-working-with-aws-lambda-triggers.html\">\nUsing Lambda triggers</a> in the <i>Amazon Cognito Developer Guide</i>.</p>\n         <note>\n            <p>When you use the <code>ClientMetadata</code> parameter, note that Amazon Cognito won't do the\n                following:</p>\n            <ul>\n               <li>\n                  <p>Store the <code>ClientMetadata</code> value. This data is available only\n                        to Lambda triggers that are assigned to a user pool to support custom\n                        workflows. If your user pool configuration doesn't include triggers, the\n                        <code>ClientMetadata</code> parameter serves no purpose.</p>\n               </li>\n               <li>\n                  <p>Validate the <code>ClientMetadata</code> value.</p>\n               </li>\n               <li>\n                  <p>Encrypt the <code>ClientMetadata</code> value. Don't send sensitive\n                        information in this parameter.</p>\n               </li>\n            </ul>\n         </note>"}))
    AdminCreateUserRequest.type = Types::AdminCreateUserRequest
    AdminCreateUserResponse.add_member(:user, Smithy::Schema::Shapes::ShapeRef.new(shape: UserType, location_name: 'User', traits: {"smithy.api#documentation" => "<p>The new user's profile details.</p>"}))
    AdminCreateUserResponse.type = Types::AdminCreateUserResponse
    AdminDeleteUserAttributesRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to delete user attributes.</p>", "smithy.api#required" => {}}))
    AdminDeleteUserAttributesRequest.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameType, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The name of the user that you want to query or modify. The value of this parameter\n            is typically your user's username, but it can be any of their alias attributes. If\n                <code>username</code> isn't an alias attribute in your user pool, this value\n            must be the <code>sub</code> of a local user or the username of a user from a\n            third-party IdP.</p>", "smithy.api#required" => {}}))
