    AdminListUserAuthEventsRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryLimitType, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of authentication events to return. Returns 60 events if you set\n                <code>MaxResults</code> to 0, or if you don't include a <code>MaxResults</code>\n            parameter.</p>"}))
