    ConfirmForgotPasswordRequest.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameType, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The name of the user that you want to query or modify. The value of this parameter\n            is typically your user's username, but it can be any of their alias attributes. If\n                <code>username</code> isn't an alias attribute in your user pool, this value\n            must be the <code>sub</code> of a local user or the username of a user from a\n            third-party IdP.</p>", "smithy.api#required" => {}}))
    ConfirmForgotPasswordRequest.add_member(:confirmation_code, Smithy::Schema::Shapes::ShapeRef.new(shape: ConfirmationCodeType, location_name: 'ConfirmationCode', traits: {"smithy.api#documentation" => "<p>The confirmation code that your user pool delivered when your user requested to reset\n            their password.</p>", "smithy.api#required" => {}}))
    ConfirmForgotPasswordRequest.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: PasswordType, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>The new password that your user wants to set.</p>", "smithy.api#required" => {}}))
    ConfirmForgotPasswordRequest.add_member(:analytics_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: AnalyticsMetadataType, location_name: 'AnalyticsMetadata', traits: {"smithy.api#documentation" => "<p>Information that supports analytics outcomes with Amazon Pinpoint, including the \nuser's endpoint ID. The endpoint ID is a destination for Amazon Pinpoint push notifications, for example a device identifier, \nemail address, or phone number.</p>"}))
    ConfirmForgotPasswordRequest.add_member(:user_context_data, Smithy::Schema::Shapes::ShapeRef.new(shape: UserContextDataType, location_name: 'UserContextData', traits: {"smithy.api#documentation" => "<p>Contextual data about your user session like the device fingerprint, IP address, or location. Amazon Cognito threat \nprotection evaluates the risk of an authentication event based on the context that your app generates and passes to Amazon Cognito\nwhen it makes API requests.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-settings-viewing-threat-protection-app.html\">Collecting data for threat protection in\napplications</a>.</p>"}))
    ConfirmForgotPasswordRequest.add_member(:client_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientMetadataType, location_name: 'ClientMetadata', traits: {"smithy.api#documentation" => "<p>A map of custom key-value pairs that you can provide as input for any custom workflows\n            that this action triggers.</p>\n         <p>You create custom workflows by assigning Lambda functions to user pool triggers.\n            When you use the ConfirmForgotPassword API action, Amazon Cognito invokes the function that is\n            assigned to the <i>post confirmation</i> trigger. When Amazon Cognito invokes this\n            function, it passes a JSON payload, which the function receives as input. This payload\n            contains a <code>clientMetadata</code> attribute, which provides the data that you\n            assigned to the ClientMetadata parameter in your ConfirmForgotPassword request. In your\n            function code in Lambda, you can process the <code>clientMetadata</code> value to\n            enhance your workflow for your specific needs.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-identity-pools-working-with-aws-lambda-triggers.html\">\nUsing Lambda triggers</a> in the <i>Amazon Cognito Developer Guide</i>.</p>\n         <note>\n            <p>When you use the <code>ClientMetadata</code> parameter, note that Amazon Cognito won't do the\n                following:</p>\n            <ul>\n               <li>\n                  <p>Store the <code>ClientMetadata</code> value. This data is available only\n                        to Lambda triggers that are assigned to a user pool to support custom\n                        workflows. If your user pool configuration doesn't include triggers, the\n                        <code>ClientMetadata</code> parameter serves no purpose.</p>\n               </li>\n               <li>\n                  <p>Validate the <code>ClientMetadata</code> value.</p>\n               </li>\n               <li>\n                  <p>Encrypt the <code>ClientMetadata</code> value. Don't send sensitive\n                        information in this parameter.</p>\n               </li>\n            </ul>\n         </note>"}))
