    ContextDataType.add_member(:server_path, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'ServerPath', traits: {"smithy.api#documentation" => "<p>The path of your application's service endpoint.</p>", "smithy.api#required" => {}}))
    ContextDataType.add_member(:http_headers, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpHeaderList, location_name: 'HttpHeaders', traits: {"smithy.api#documentation" => "<p>The HTTP headers from your user's authentication request.</p>", "smithy.api#required" => {}}))
    ContextDataType.add_member(:encoded_data, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'EncodedData', traits: {"smithy.api#documentation" => "<p>Encoded device-fingerprint details that your app collected with the Amazon Cognito\n            context data collection library. For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pool-settings-adaptive-authentication.html#user-pool-settings-adaptive-authentication-device-fingerprint\">Adding user device and session data to API requests</a>.</p>"}))
