    CreateGroupRequest.add_member(:group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupNameType, location_name: 'GroupName', traits: {"smithy.api#documentation" => "<p>A name for the group. This name must be unique in your user pool.</p>", "smithy.api#required" => {}}))
    CreateGroupRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to create a user group.</p>", "smithy.api#required" => {}}))
    CreateGroupRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the group that you're creating.</p>"}))
    CreateGroupRequest.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM role that you want to associate with the\n            group. A group role primarily declares a preferred role for the credentials that you get\n            from an identity pool. Amazon Cognito ID tokens have a <code>cognito:preferred_role</code> claim\n            that presents the highest-precedence group that a user belongs to. Both ID and access\n            tokens also contain a <code>cognito:groups</code> claim that list all the groups that a\n            user is a member of.</p>"}))
    CreateGroupRequest.add_member(:precedence, Smithy::Schema::Shapes::ShapeRef.new(shape: PrecedenceType, location_name: 'Precedence', traits: {"smithy.api#documentation" => "<p>A non-negative integer value that specifies the precedence of this group relative to\n            the other groups that a user can belong to in the user pool. Zero is the highest\n            precedence value. Groups with lower <code>Precedence</code> values take precedence over\n            groups with higher or null <code>Precedence</code> values. If a user belongs to two or\n            more groups, it is the group with the lowest precedence value whose role ARN is given in\n            the user's tokens for the <code>cognito:roles</code> and\n                <code>cognito:preferred_role</code> claims.</p>\n         <p>Two groups can have the same <code>Precedence</code> value. If this happens, neither\n            group takes precedence over the other. If two groups with the same\n                <code>Precedence</code> have the same role ARN, that role is used in the\n                <code>cognito:preferred_role</code> claim in tokens for users in each group. If the\n            two groups have different role ARNs, the <code>cognito:preferred_role</code> claim isn't\n            set in users' tokens.</p>\n         <p>The default <code>Precedence</code> value is null. The maximum <code>Precedence</code>\n            value is <code>2^31-1</code>.</p>"}))
    CreateGroupRequest.type = Types::CreateGroupRequest
    CreateGroupResponse.add_member(:group, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupType, location_name: 'Group', traits: {"smithy.api#documentation" => "<p>The response object for a created group.</p>"}))
