    DescribeResourceServerRequest.add_member(:identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceServerIdentifierType, location_name: 'Identifier', traits: {"smithy.api#documentation" => "<p>A unique resource server identifier for the resource server. The identifier can be an\n            API friendly name like <code>solar-system-data</code>. You can also set an API URL like\n                <code>https://solar-system-data-api.example.com</code> as your identifier.</p>\n         <p>Amazon Cognito represents scopes in the access token in the format\n                <code>$resource-server-identifier/$scope</code>. Longer scope-identifier strings\n            increase the size of your access tokens.</p>", "smithy.api#required" => {}}))
