    DeviceConfigurationType.add_member(:challenge_required_on_new_device, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'ChallengeRequiredOnNewDevice', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>When true, a remembered device can sign in with device authentication instead of SMS\n            and time-based one-time password (TOTP) factors for multi-factor authentication\n            (MFA).</p>\n         <note>\n            <p>Whether or not <code>ChallengeRequiredOnNewDevice</code> is true, users who sign\n                in with devices that have not been confirmed or remembered must still provide a\n                second factor in a user pool that requires MFA.</p>\n         </note>"}))
    DeviceConfigurationType.add_member(:device_only_remembered_on_user_prompt, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'DeviceOnlyRememberedOnUserPrompt', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>When true, Amazon Cognito doesn't automatically remember a user's device when your app sends a\n                <code>ConfirmDevice</code> API request. In your app, create a prompt for your user\n            to choose whether they want to remember their device. Return the user's choice in an\n                <code>UpdateDeviceStatus</code> API request.</p>\n         <p>When <code>DeviceOnlyRememberedOnUserPrompt</code> is <code>false</code>, Amazon\n            Cognito immediately remembers devices that you register in a <code>ConfirmDevice</code>\n            API request.</p>"}))
