    GetUserPoolMfaConfigResponse.add_member(:sms_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SmsMfaConfigType, location_name: 'SmsMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Shows user pool configuration for SMS message MFA. Includes the message template and\n            the SMS message sending configuration for Amazon SNS.</p>"}))
    GetUserPoolMfaConfigResponse.add_member(:software_token_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SoftwareTokenMfaConfigType, location_name: 'SoftwareTokenMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Shows user pool configuration for time-based one-time password (TOTP) MFA. Includes\n            TOTP enabled or disabled state.</p>"}))
    GetUserPoolMfaConfigResponse.add_member(:email_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailMfaConfigType, location_name: 'EmailMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Shows configuration for user pool email message MFA and sign-in with one-time\n            passwords (OTPs). Includes the subject and body of the email message template for\n            sign-in and MFA messages. To activate this setting, your user pool must be in the <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/feature-plans-features-essentials.html\">\n                     Essentials tier</a> or higher.</p>"}))
    GetUserPoolMfaConfigResponse.add_member(:mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolMfaType, location_name: 'MfaConfiguration', traits: {"smithy.api#documentation" => "<p>Displays the state of multi-factor authentication (MFA) as on, off, or optional. When\n                <code>ON</code>, all users must set up MFA before they can sign in. When\n                <code>OPTIONAL</code>, your application must make a client-side determination of\n            whether a user wants to register an MFA device. For user pools with adaptive\n            authentication with threat protection, choose <code>OPTIONAL</code>.</p>\n         <p>When <code>MfaConfiguration</code> is <code>OPTIONAL</code>, managed login\n            doesn't automatically prompt users to set up MFA. Amazon Cognito generates MFA prompts in\n            API responses and in managed login for users who have chosen and configured a preferred\n            MFA factor.</p>"}))
    GetUserPoolMfaConfigResponse.add_member(:web_authn_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAuthnConfigurationType, location_name: 'WebAuthnConfiguration', traits: {"smithy.api#documentation" => "<p>Shows user pool configuration for sign-in with passkey authenticators like biometric\n            devices and security keys. Passkeys are not eligible MFA factors. They are instead an\n            eligible primary sign-in factor for <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/authentication-flows-selection-sdk.html#authentication-flows-selection-choice\">choice-based authentication</a>, or the\n                <code>USER_AUTH</code> flow.</p>"}))
