    GetUserResponse.add_member(:user_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeListType, location_name: 'UserAttributes', traits: {"smithy.api#documentation" => "<p>An array of name-value pairs representing user attributes.</p>\n         <p>Custom attributes are prepended with the <code>custom:</code> prefix.</p>", "smithy.api#required" => {}}))
    GetUserResponse.add_member(:mfa_options, Smithy::Schema::Shapes::ShapeRef.new(shape: MFAOptionListType, location_name: 'MFAOptions', traits: {"smithy.api#documentation" => "<p>\n            <i>This response parameter is no longer supported.</i> It provides\n            information only about SMS MFA configurations. It doesn't provide information about\n            time-based one-time password (TOTP) software token MFA configurations. To look up\n            information about either type of MFA configuration, use UserMFASettingList\n            instead.</p>"}))
    GetUserResponse.add_member(:preferred_mfa_setting, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'PreferredMfaSetting', traits: {"smithy.api#documentation" => "<p>The user's preferred MFA. Users can prefer SMS message, email message, or TOTP\n            MFA.</p>"}))
