    GroupType.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool that contains the group.</p>"}))
    GroupType.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: DescriptionType, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A friendly description of the group.</p>"}))
    GroupType.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role associated with the group. If a group has the highest\n            priority of a user's groups, users who authenticate with an identity pool get\n            credentials for the <code>RoleArn</code> that's associated with the group.</p>"}))
    GroupType.add_member(:precedence, Smithy::Schema::Shapes::ShapeRef.new(shape: PrecedenceType, location_name: 'Precedence', traits: {"smithy.api#documentation" => "<p>A non-negative integer value that specifies the precedence of this group relative to\n            the other groups that a user can belong to in the user pool. Zero is the highest\n            precedence value. Groups with lower <code>Precedence</code> values take precedence over\n            groups with higher ornull <code>Precedence</code> values. If a user belongs to two or\n            more groups, it is the group with the lowest precedence value whose role ARN is given in\n            the user's tokens for the <code>cognito:roles</code> and\n                <code>cognito:preferred_role</code> claims.</p>\n         <p>Two groups can have the same <code>Precedence</code> value. If this happens, neither\n            group takes precedence over the other. If two groups with the same\n                <code>Precedence</code> have the same role ARN, that role is used in the\n                <code>cognito:preferred_role</code> claim in tokens for users in each group. If the\n            two groups have different role ARNs, the <code>cognito:preferred_role</code> claim isn't\n            set in users' tokens.</p>\n         <p>The default <code>Precedence</code> value is <code>null</code>.</p>"}))
    GroupType.add_member(:last_modified_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'LastModifiedDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was modified. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
    GroupType.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was created. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
