    RespondToAuthChallengeRequest.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientIdType, location_name: 'ClientId', traits: {"smithy.api#documentation" => "<p>The ID of the app client where the user is signing in.</p>", "smithy.api#required" => {}}))
    RespondToAuthChallengeRequest.add_member(:challenge_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeNameType, location_name: 'ChallengeName', traits: {"smithy.api#documentation" => "<p>The name of the challenge that you are responding to.</p>\n         <note>\n            <p>You can't respond to an <code>ADMIN_NO_SRP_AUTH</code> challenge with this\n                operation.</p>\n         </note>\n         <p>Possible challenges include the following:</p>\n         <note>\n            <p>All of the following challenges require <code>USERNAME</code> and, when the app\n                client has a client secret, <code>SECRET_HASH</code> in the parameters.</p>\n         </note>\n         <ul>\n            <li>\n               <p>\n                  <code>WEB_AUTHN</code>: Respond to the challenge with the results of a\n                    successful authentication with a WebAuthn authenticator, or passkey. Examples \n                    of WebAuthn authenticators include biometric devices and security keys.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PASSWORD</code>: Respond with <code>USER_PASSWORD_AUTH</code>\n                    parameters: <code>USERNAME</code> (required), <code>PASSWORD</code> (required),\n                        <code>SECRET_HASH</code> (required if the app client is configured with a\n                    client secret), <code>DEVICE_KEY</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PASSWORD_SRP</code>: Respond with <code>USER_SRP_AUTH</code> parameters:\n                        <code>USERNAME</code> (required), <code>SRP_A</code> (required),\n                        <code>SECRET_HASH</code> (required if the app client is configured with a\n                    client secret), <code>DEVICE_KEY</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SELECT_CHALLENGE</code>: Respond to the challenge with\n                        <code>USERNAME</code> and an <code>ANSWER</code> that matches one of the\n                    challenge types in the <code>AvailableChallenges</code> response\n                    parameter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SMS_MFA</code>: Respond with an\n                    <code>SMS_MFA_CODE</code> that your user pool delivered in an SMS message.</p>\n            </li>\n            <li>\n               <p>\n                  <code>EMAIL_OTP</code>: Respond with an\n                        <code>EMAIL_OTP_CODE</code> that your user pool delivered in an email\n                    message.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PASSWORD_VERIFIER</code>: Respond with\n                        <code>PASSWORD_CLAIM_SIGNATURE</code>,\n                        <code>PASSWORD_CLAIM_SECRET_BLOCK</code>, and <code>TIMESTAMP</code> after\n                    client-side SRP calculations.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CUSTOM_CHALLENGE</code>: This is returned if your custom authentication\n                    flow determines that the user should pass another challenge before tokens are\n                    issued. The parameters of the challenge are determined by your Lambda function.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DEVICE_SRP_AUTH</code>: Respond with the initial parameters of device SRP \n                authentication. For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/amazon-cognito-user-pools-device-tracking.html#user-pools-remembered-devices-signing-in-with-a-device\">Signing in with a device</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DEVICE_PASSWORD_VERIFIER</code>: Respond with\n                        <code>PASSWORD_CLAIM_SIGNATURE</code>,\n                        <code>PASSWORD_CLAIM_SECRET_BLOCK</code>, and <code>TIMESTAMP</code> after\n                    client-side SRP calculations. For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/amazon-cognito-user-pools-device-tracking.html#user-pools-remembered-devices-signing-in-with-a-device\">Signing in with a device</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW_PASSWORD_REQUIRED</code>: For users who are required to change their\n                    passwords after successful first login. Respond to this challenge with \n                    <code>NEW_PASSWORD</code> and any required attributes that Amazon Cognito returned in \n                    the <code>requiredAttributes</code> parameter. You can also set values for \n                    attributes that aren't required by your user pool and that your app client \n                    can write.</p>\n               <p>Amazon Cognito only returns this challenge for users who have temporary passwords.\n                    When you create passwordless users, you must provide values for all required \n                    attributes.</p>\n               <note>\n                  <p>In a <code>NEW_PASSWORD_REQUIRED</code> challenge response, you can't modify a required attribute that already has a value. \nIn <code>AdminRespondToAuthChallenge</code> or <code>RespondToAuthChallenge</code>, set a value for any keys that Amazon Cognito returned in the \n<code>requiredAttributes</code> parameter, then use the <code>AdminUpdateUserAttributes</code> or <code>UpdateUserAttributes</code> API \noperation to modify the value of any additional attributes.</p>\n               </note>\n            </li>\n            <li>\n               <p>\n                  <code>MFA_SETUP</code>: For users who are required to setup an MFA factor\n                    before they can sign in. The MFA types activated for the user pool will be\n                    listed in the challenge parameters <code>MFAS_CAN_SETUP</code> value. </p>\n               <p>To set up time-based one-time password (TOTP) MFA, use the session returned \n                    in this challenge from <code>InitiateAuth</code> or <code>AdminInitiateAuth</code> \n                    as an input to <code>AssociateSoftwareToken</code>. Then, use the session returned\n                    by <code>VerifySoftwareToken</code> as an input to \n                    <code>RespondToAuthChallenge</code> or <code>AdminRespondToAuthChallenge</code>\n                with challenge name <code>MFA_SETUP</code> to complete sign-in.\n                </p>\n               <p>To set up SMS or email MFA, collect a <code>phone_number</code> or \n                    <code>email</code> attribute for the user. Then restart the authentication \n                    flow with an <code>InitiateAuth</code> or <code>AdminInitiateAuth</code> request.\n                </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    RespondToAuthChallengeRequest.add_member(:session, Smithy::Schema::Shapes::ShapeRef.new(shape: SessionType, location_name: 'Session', traits: {"smithy.api#documentation" => "<p>The session identifier that maintains the state of authentication requests and\n            challenge responses. If an <code>AdminInitiateAuth</code> or\n                <code>AdminRespondToAuthChallenge</code> API request results in a determination that\n            your application must pass another challenge, Amazon Cognito returns a session with other\n            challenge parameters. Send this session identifier, unmodified, to the next\n                <code>AdminRespondToAuthChallenge</code> request.</p>"}))
    RespondToAuthChallengeRequest.add_member(:challenge_responses, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeResponsesType, location_name: 'ChallengeResponses', traits: {"smithy.api#documentation" => "<p>The responses to the challenge that you received in the previous request. Each\n    challenge has its own required response parameters. The following examples are partial\n    JSON request bodies that highlight challenge-response parameters.</p>\n         <important>\n            <p>You must provide a SECRET_HASH parameter in all challenge responses to an app\n        client that has a client secret. Include a <code>DEVICE_KEY</code> for device\n        authentication.</p>\n         </important>\n         <dl>\n            <dt>SELECT_CHALLENGE</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"SELECT_CHALLENGE\", \"ChallengeResponses\": {\n            \"USERNAME\": \"[username]\",\n            \"ANSWER\": \"[Challenge name]\"}</code>\n               </p>\n               <p>Available challenges are <code>PASSWORD</code>, <code>PASSWORD_SRP</code>, \n            <code>EMAIL_OTP</code>, <code>SMS_OTP</code>, and <code>WEB_AUTHN</code>.</p>\n               <p>Complete authentication in the <code>SELECT_CHALLENGE</code> response for\n            <code>PASSWORD</code>, <code>PASSWORD_SRP</code>, and <code>WEB_AUTHN</code>:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>\"ChallengeName\": \"SELECT_CHALLENGE\", \"ChallengeResponses\": {\n                  \"ANSWER\": \"WEB_AUTHN\",\n                  \"USERNAME\": \"[username]\",\n                  \"CREDENTIAL\": \"[AuthenticationResponseJSON]\"}</code>\n                     </p>\n                     <p>See <a href=\"https://www.w3.org/TR/WebAuthn-3/#dictdef-authenticationresponsejson\">\n                  AuthenticationResponseJSON</a>.</p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>\"ChallengeName\": \"SELECT_CHALLENGE\", \"ChallengeResponses\": {\n                  \"ANSWER\": \"PASSWORD\",\n                  \"USERNAME\": \"[username]\",\n                  \"PASSWORD\": \"[password]\"}</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>\"ChallengeName\": \"SELECT_CHALLENGE\", \"ChallengeResponses\": {\n                  \"ANSWER\": \"PASSWORD_SRP\",\n                  \"USERNAME\": \"[username]\",\n                  \"SRP_A\": \"[SRP_A]\"}</code>\n                     </p>\n                  </li>\n               </ul>\n               <p>For <code>SMS_OTP</code> and <code>EMAIL_OTP</code>, respond with the\n            username and answer. Your user pool will send a code for the user to submit in\n            the next challenge response.</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>\"ChallengeName\": \"SELECT_CHALLENGE\", \"ChallengeResponses\": {\n                  \"ANSWER\": \"SMS_OTP\",\n                  \"USERNAME\": \"[username]\"}</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>\"ChallengeName\": \"SELECT_CHALLENGE\", \"ChallengeResponses\": {\n                  \"ANSWER\": \"EMAIL_OTP\",\n                  \"USERNAME\": \"[username]\"}</code>\n                     </p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>SMS_OTP</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"SMS_OTP\", \"ChallengeResponses\": \n            {\"SMS_OTP_CODE\": \"[code]\", \"USERNAME\": \"[username]\"}</code>\n               </p>\n            </dd>\n            <dt>EMAIL_OTP</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"EMAIL_OTP\", \"ChallengeResponses\": {\"EMAIL_OTP_CODE\":\n                    \"[code]\", \"USERNAME\": \"[username]\"}</code>\n               </p>\n            </dd>\n            <dt>SMS_MFA</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"SMS_MFA\", \"ChallengeResponses\": {\"SMS_MFA_CODE\":\n                    \"[code]\", \"USERNAME\": \"[username]\"}</code>\n               </p>\n            </dd>\n            <dt>PASSWORD_VERIFIER</dt>\n            <dd>\n               <p>This challenge response is part of the SRP flow. Amazon Cognito requires \n            that your application respond to this challenge within a few seconds. When\n            the response time exceeds this period, your user pool returns a\n            <code>NotAuthorizedException</code> error.</p>\n               <p>\n                  <code>\"ChallengeName\": \"PASSWORD_VERIFIER\", \"ChallengeResponses\":\n                    {\"PASSWORD_CLAIM_SIGNATURE\": \"[claim_signature]\",\n                    \"PASSWORD_CLAIM_SECRET_BLOCK\": \"[secret_block]\", \"TIMESTAMP\":\n                    [timestamp], \"USERNAME\": \"[username]\"}</code>\n               </p>\n               <p>Add <code>\"DEVICE_KEY\"</code> when you sign in with a remembered\n                device.</p>\n            </dd>\n            <dt>CUSTOM_CHALLENGE</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"CUSTOM_CHALLENGE\", \"ChallengeResponses\":\n                    {\"USERNAME\": \"[username]\", \"ANSWER\": \"[challenge_answer]\"}</code>\n               </p>\n               <p>Add <code>\"DEVICE_KEY\"</code> when you sign in with a remembered\n                device.</p>\n            </dd>\n            <dt>NEW_PASSWORD_REQUIRED</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"NEW_PASSWORD_REQUIRED\", \"ChallengeResponses\":\n                    {\"NEW_PASSWORD\": \"[new_password]\", \"USERNAME\":\n                \"[username]\"}</code>\n               </p>\n               <p>To set any required attributes that <code>InitiateAuth</code> returned in\n                an <code>requiredAttributes</code> parameter, add\n                    <code>\"userAttributes.[attribute_name]\": \"[attribute_value]\"</code>.\n                This parameter can also set values for writable attributes that aren't\n                required by your user pool.</p>\n               <note>\n                  <p>In a <code>NEW_PASSWORD_REQUIRED</code> challenge response, you can't modify a required attribute that already has a value. \nIn <code>AdminRespondToAuthChallenge</code> or <code>RespondToAuthChallenge</code>, set a value for any keys that Amazon Cognito returned in the \n<code>requiredAttributes</code> parameter, then use the <code>AdminUpdateUserAttributes</code> or <code>UpdateUserAttributes</code> API \noperation to modify the value of any additional attributes.</p>\n               </note>\n            </dd>\n            <dt>SOFTWARE_TOKEN_MFA</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"SOFTWARE_TOKEN_MFA\", \"ChallengeResponses\":\n                    {\"USERNAME\": \"[username]\", \"SOFTWARE_TOKEN_MFA_CODE\":\n                    [authenticator_code]}</code>\n               </p>\n            </dd>\n            <dt>DEVICE_SRP_AUTH</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"DEVICE_SRP_AUTH\", \"ChallengeResponses\": {\"USERNAME\":\n                \"[username]\", \"DEVICE_KEY\": \"[device_key]\", \"SRP_A\":\n                \"[srp_a]\"}</code>\n               </p>\n            </dd>\n            <dt>DEVICE_PASSWORD_VERIFIER</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"DEVICE_PASSWORD_VERIFIER\", \"ChallengeResponses\":\n                {\"DEVICE_KEY\": \"[device_key]\", \"PASSWORD_CLAIM_SIGNATURE\":\n                \"[claim_signature]\", \"PASSWORD_CLAIM_SECRET_BLOCK\": \"[secret_block]\",\n                \"TIMESTAMP\": [timestamp], \"USERNAME\": \"[username]\"}</code>\n               </p>\n            </dd>\n            <dt>MFA_SETUP</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"MFA_SETUP\", \"ChallengeResponses\": {\"USERNAME\":\n                \"[username]\"}, \"SESSION\": \"[Session ID from\n                VerifySoftwareToken]\"</code>\n               </p>\n            </dd>\n            <dt>SELECT_MFA_TYPE</dt>\n            <dd>\n               <p>\n                  <code>\"ChallengeName\": \"SELECT_MFA_TYPE\", \"ChallengeResponses\": {\"USERNAME\":\n                \"[username]\", \"ANSWER\": \"[SMS_MFA or SOFTWARE_TOKEN_MFA]\"}</code>\n               </p>\n            </dd>\n         </dl>\n         <p>For more information about <code>SECRET_HASH</code>, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/signing-up-users-in-your-app.html#cognito-user-pools-computing-secret-hash\">Computing secret hash values</a>. For information about\n    <code>DEVICE_KEY</code>, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/amazon-cognito-user-pools-device-tracking.html\">Working with user devices in your user pool</a>.</p>"}))
    RespondToAuthChallengeRequest.add_member(:analytics_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: AnalyticsMetadataType, location_name: 'AnalyticsMetadata', traits: {"smithy.api#documentation" => "<p>Information that supports analytics outcomes with Amazon Pinpoint, including the \nuser's endpoint ID. The endpoint ID is a destination for Amazon Pinpoint push notifications, for example a device identifier, \nemail address, or phone number.</p>"}))
    RespondToAuthChallengeRequest.add_member(:user_context_data, Smithy::Schema::Shapes::ShapeRef.new(shape: UserContextDataType, location_name: 'UserContextData', traits: {"smithy.api#documentation" => "<p>Contextual data about your user session like the device fingerprint, IP address, or location. Amazon Cognito threat \nprotection evaluates the risk of an authentication event based on the context that your app generates and passes to Amazon Cognito\nwhen it makes API requests.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-settings-viewing-threat-protection-app.html\">Collecting data for threat protection in\napplications</a>.</p>"}))
    RespondToAuthChallengeRequest.add_member(:client_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientMetadataType, location_name: 'ClientMetadata', traits: {"smithy.api#documentation" => "<p>A map of custom key-value pairs that you can provide as input for any custom workflows\n            that this action triggers.</p>\n         <p>You create custom workflows by assigning Lambda functions to user pool\n            triggers. When you use the RespondToAuthChallenge API action, Amazon Cognito invokes any\n            functions that are assigned to the following triggers: <i>post\n                authentication</i>, <i>pre token generation</i>,\n                <i>define auth challenge</i>, <i>create auth\n                challenge</i>, and <i>verify auth challenge</i>. When Amazon Cognito\n            invokes any of these functions, it passes a JSON payload, which the function receives as\n            input. This payload contains a <code>clientMetadata</code> attribute, which provides the\n            data that you assigned to the ClientMetadata parameter in your RespondToAuthChallenge\n            request. In your function code in Lambda, you can process the\n                <code>clientMetadata</code> value to enhance your workflow for your specific\n            needs.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-identity-pools-working-with-aws-lambda-triggers.html\">\nUsing Lambda triggers</a> in the <i>Amazon Cognito Developer Guide</i>.</p>\n         <note>\n            <p>When you use the <code>ClientMetadata</code> parameter, note that Amazon Cognito won't do the\n                following:</p>\n            <ul>\n               <li>\n                  <p>Store the <code>ClientMetadata</code> value. This data is available only\n                        to Lambda triggers that are assigned to a user pool to support custom\n                        workflows. If your user pool configuration doesn't include triggers, the\n                        <code>ClientMetadata</code> parameter serves no purpose.</p>\n               </li>\n               <li>\n                  <p>Validate the <code>ClientMetadata</code> value.</p>\n               </li>\n               <li>\n                  <p>Encrypt the <code>ClientMetadata</code> value. Don't send sensitive\n                        information in this parameter.</p>\n               </li>\n            </ul>\n         </note>"}))
    RespondToAuthChallengeRequest.type = Types::RespondToAuthChallengeRequest
    RespondToAuthChallengeResponse.add_member(:challenge_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeNameType, location_name: 'ChallengeName', traits: {"smithy.api#documentation" => "<p>The name of the next challenge that you must respond to.</p>\n         <p>Possible challenges include the following:</p>\n         <note>\n            <p>All of the following challenges require <code>USERNAME</code> and, when the app\n                client has a client secret, <code>SECRET_HASH</code> in the parameters.</p>\n         </note>\n         <ul>\n            <li>\n               <p>\n                  <code>WEB_AUTHN</code>: Respond to the challenge with the results of a\n                    successful authentication with a WebAuthn authenticator, or passkey. Examples \n                    of WebAuthn authenticators include biometric devices and security keys.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PASSWORD</code>: Respond with <code>USER_PASSWORD_AUTH</code>\n                    parameters: <code>USERNAME</code> (required), <code>PASSWORD</code> (required),\n                        <code>SECRET_HASH</code> (required if the app client is configured with a\n                    client secret), <code>DEVICE_KEY</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PASSWORD_SRP</code>: Respond with <code>USER_SRP_AUTH</code> parameters:\n                        <code>USERNAME</code> (required), <code>SRP_A</code> (required),\n                        <code>SECRET_HASH</code> (required if the app client is configured with a\n                    client secret), <code>DEVICE_KEY</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SELECT_CHALLENGE</code>: Respond to the challenge with\n                        <code>USERNAME</code> and an <code>ANSWER</code> that matches one of the\n                    challenge types in the <code>AvailableChallenges</code> response\n                    parameter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SMS_MFA</code>: Respond with an\n                    <code>SMS_MFA_CODE</code> that your user pool delivered in an SMS message.</p>\n            </li>\n            <li>\n               <p>\n                  <code>EMAIL_OTP</code>: Respond with an\n                        <code>EMAIL_OTP_CODE</code> that your user pool delivered in an email\n                    message.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PASSWORD_VERIFIER</code>: Respond with\n                        <code>PASSWORD_CLAIM_SIGNATURE</code>,\n                        <code>PASSWORD_CLAIM_SECRET_BLOCK</code>, and <code>TIMESTAMP</code> after\n                    client-side SRP calculations.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CUSTOM_CHALLENGE</code>: This is returned if your custom authentication\n                    flow determines that the user should pass another challenge before tokens are\n                    issued. The parameters of the challenge are determined by your Lambda function.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DEVICE_SRP_AUTH</code>: Respond with the initial parameters of device SRP \n                authentication. For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/amazon-cognito-user-pools-device-tracking.html#user-pools-remembered-devices-signing-in-with-a-device\">Signing in with a device</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DEVICE_PASSWORD_VERIFIER</code>: Respond with\n                        <code>PASSWORD_CLAIM_SIGNATURE</code>,\n                        <code>PASSWORD_CLAIM_SECRET_BLOCK</code>, and <code>TIMESTAMP</code> after\n                    client-side SRP calculations. For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/amazon-cognito-user-pools-device-tracking.html#user-pools-remembered-devices-signing-in-with-a-device\">Signing in with a device</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NEW_PASSWORD_REQUIRED</code>: For users who are required to change their\n                    passwords after successful first login. Respond to this challenge with \n                    <code>NEW_PASSWORD</code> and any required attributes that Amazon Cognito returned in \n                    the <code>requiredAttributes</code> parameter. You can also set values for \n                    attributes that aren't required by your user pool and that your app client \n                    can write.</p>\n               <p>Amazon Cognito only returns this challenge for users who have temporary passwords.\n                    When you create passwordless users, you must provide values for all required \n                    attributes.</p>\n               <note>\n                  <p>In a <code>NEW_PASSWORD_REQUIRED</code> challenge response, you can't modify a required attribute that already has a value. \nIn <code>AdminRespondToAuthChallenge</code> or <code>RespondToAuthChallenge</code>, set a value for any keys that Amazon Cognito returned in the \n<code>requiredAttributes</code> parameter, then use the <code>AdminUpdateUserAttributes</code> or <code>UpdateUserAttributes</code> API \noperation to modify the value of any additional attributes.</p>\n               </note>\n            </li>\n            <li>\n               <p>\n                  <code>MFA_SETUP</code>: For users who are required to setup an MFA factor\n                    before they can sign in. The MFA types activated for the user pool will be\n                    listed in the challenge parameters <code>MFAS_CAN_SETUP</code> value. </p>\n               <p>To set up time-based one-time password (TOTP) MFA, use the session returned \n                    in this challenge from <code>InitiateAuth</code> or <code>AdminInitiateAuth</code> \n                    as an input to <code>AssociateSoftwareToken</code>. Then, use the session returned\n                    by <code>VerifySoftwareToken</code> as an input to \n                    <code>RespondToAuthChallenge</code> or <code>AdminRespondToAuthChallenge</code>\n                with challenge name <code>MFA_SETUP</code> to complete sign-in.\n                </p>\n               <p>To set up SMS or email MFA, collect a <code>phone_number</code> or \n                    <code>email</code> attribute for the user. Then restart the authentication \n                    flow with an <code>InitiateAuth</code> or <code>AdminInitiateAuth</code> request.\n                </p>\n            </li>\n         </ul>"}))
    RespondToAuthChallengeResponse.add_member(:session, Smithy::Schema::Shapes::ShapeRef.new(shape: SessionType, location_name: 'Session', traits: {"smithy.api#documentation" => "<p>The session identifier that maintains the state of authentication requests and\n            challenge responses. If an <code>InitiateAuth</code> or\n                <code>RespondToAuthChallenge</code> API request results in a determination that your\n            application must pass another challenge, Amazon Cognito returns a session with other challenge\n            parameters. Send this session identifier, unmodified, to the next\n                <code>RespondToAuthChallenge</code> request.</p>"}))
    RespondToAuthChallengeResponse.add_member(:challenge_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeParametersType, location_name: 'ChallengeParameters', traits: {"smithy.api#documentation" => "<p>The parameters that define your response to the next challenge.</p>"}))
    RespondToAuthChallengeResponse.add_member(:authentication_result, Smithy::Schema::Shapes::ShapeRef.new(shape: AuthenticationResultType, location_name: 'AuthenticationResult', traits: {"smithy.api#documentation" => "<p>The outcome of a successful authentication process. After your application has passed\n            all challenges, Amazon Cognito returns an <code>AuthenticationResult</code> with the JSON web\n            tokens (JWTs) that indicate successful sign-in.</p>"}))
    RespondToAuthChallengeResponse.type = Types::RespondToAuthChallengeResponse
    RevokeTokenRequest.add_member(:token, Smithy::Schema::Shapes::ShapeRef.new(shape: TokenModelType, location_name: 'Token', traits: {"smithy.api#documentation" => "<p>The refresh token that you want to revoke.</p>", "smithy.api#required" => {}}))
    RevokeTokenRequest.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientIdType, location_name: 'ClientId', traits: {"smithy.api#documentation" => "<p>The ID of the app client where the token that you want to revoke was issued.</p>", "smithy.api#required" => {}}))
    RevokeTokenRequest.add_member(:client_secret, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientSecretType, location_name: 'ClientSecret', traits: {"smithy.api#documentation" => "<p>The client secret of the requested app client, if the client has a secret.</p>"}))
    RevokeTokenRequest.type = Types::RevokeTokenRequest
    RevokeTokenResponse.type = Types::RevokeTokenResponse
    RiskConfigurationType.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool that has the risk configuration applied.</p>"}))
    RiskConfigurationType.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientIdType, location_name: 'ClientId', traits: {"smithy.api#documentation" => "<p>The app client where this configuration is applied. When this parameter isn't present,\n            the risk configuration applies to all user pool app clients that don't have\n            client-level settings.</p>"}))
    RiskConfigurationType.add_member(:compromised_credentials_risk_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CompromisedCredentialsRiskConfigurationType, location_name: 'CompromisedCredentialsRiskConfiguration', traits: {"smithy.api#documentation" => "<p>Settings for compromised-credentials actions and authentication types with threat\n            protection in full-function <code>ENFORCED</code> mode.</p>"}))
    RiskConfigurationType.add_member(:account_takeover_risk_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverRiskConfigurationType, location_name: 'AccountTakeoverRiskConfiguration', traits: {"smithy.api#documentation" => "<p>The settings for automated responses and notification templates for adaptive\n            authentication with threat protection.</p>"}))
    RiskConfigurationType.add_member(:risk_exception_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RiskExceptionConfigurationType, location_name: 'RiskExceptionConfiguration', traits: {"smithy.api#documentation" => "<p>Exceptions to the risk evaluation configuration, including always-allow and\n            always-block IP address ranges. </p>"}))
    RiskConfigurationType.add_member(:last_modified_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'LastModifiedDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was modified. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
    RiskConfigurationType.type = Types::RiskConfigurationType
    RiskDecisionType.add_member(:no_risk, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NoRisk', traits: {"smithy.api#enumValue" => "NoRisk"}))
    RiskDecisionType.add_member(:account_takeover, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AccountTakeover', traits: {"smithy.api#enumValue" => "AccountTakeover"}))
    RiskDecisionType.add_member(:block, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Block', traits: {"smithy.api#enumValue" => "Block"}))
    RiskExceptionConfigurationType.add_member(:blocked_ip_range_list, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockedIPRangeListType, location_name: 'BlockedIPRangeList', traits: {"smithy.api#documentation" => "<p>An always-block IP address list. Overrides the risk decision and always blocks\n            authentication requests. This parameter is displayed and set in CIDR notation.</p>"}))
    RiskExceptionConfigurationType.add_member(:skipped_ip_range_list, Smithy::Schema::Shapes::ShapeRef.new(shape: SkippedIPRangeListType, location_name: 'SkippedIPRangeList', traits: {"smithy.api#documentation" => "<p>An always-allow IP address list. Risk detection isn't performed on the IP addresses in\n            this range list. This parameter is displayed and set in CIDR notation.</p>"}))
    RiskExceptionConfigurationType.type = Types::RiskExceptionConfigurationType
    RiskLevelType.add_member(:low, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Low', traits: {"smithy.api#enumValue" => "Low"}))
    RiskLevelType.add_member(:medium, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Medium', traits: {"smithy.api#enumValue" => "Medium"}))
    RiskLevelType.add_member(:high, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'High', traits: {"smithy.api#enumValue" => "High"}))
    S3ConfigurationType.add_member(:bucket_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: S3ArnType, location_name: 'BucketArn', traits: {"smithy.api#documentation" => "<p>The ARN of an Amazon S3 bucket that's the destination for threat protection log\n            export.</p>"}))
    S3ConfigurationType.type = Types::S3ConfigurationType
    SMSMfaSettingsType.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'Enabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether SMS message MFA is activated. If an MFA type is activated for a\n            user, the user will be prompted for MFA during all sign-in attempts, unless device\n            tracking is turned on and the device has been trusted.</p>"}))
    SMSMfaSettingsType.add_member(:preferred_mfa, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'PreferredMfa', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether SMS is the preferred MFA method. If true, your user pool prompts the\n            specified user for a code delivered by SMS message after username-password sign-in\n            succeeds. </p>"}))
    SMSMfaSettingsType.type = Types::SMSMfaSettingsType
    SchemaAttributeType.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomAttributeNameType, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of your user pool attribute. When you create or update a user pool, adding a\n            schema attribute creates a custom or developer-only attribute. When you add an attribute\n            with a <code>Name</code> value of <code>MyAttribute</code>, Amazon Cognito creates the custom\n            attribute <code>custom:MyAttribute</code>. When <code>DeveloperOnlyAttribute</code> is\n                <code>true</code>, Amazon Cognito creates your attribute as <code>dev:MyAttribute</code>. In\n            an operation that describes a user pool, Amazon Cognito returns this value as <code>value</code>\n            for standard attributes, <code>custom:value</code> for custom attributes, and\n                <code>dev:value</code> for developer-only attributes..</p>"}))
    SchemaAttributeType.add_member(:attribute_data_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeDataType, location_name: 'AttributeDataType', traits: {"smithy.api#documentation" => "<p>The data format of the values for your attribute. When you choose an\n                <code>AttributeDataType</code>, Amazon Cognito validates the input against the data type. A\n            custom attribute value in your user's ID token is always a string, for example\n                <code>\"custom:isMember\" : \"true\"</code> or <code>\"custom:YearsAsMember\" :\n                \"12\"</code>. </p>"}))
    SchemaAttributeType.add_member(:developer_only_attribute, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'DeveloperOnlyAttribute', traits: {"smithy.api#default" => nil, "smithy.api#documentation" => "<note>\n            <p>You should use <a href=\"https://docs.aws.amazon.com/cognito-user-identity-pools/latest/APIReference/API_UserPoolClientType.html#CognitoUserPools-Type-UserPoolClientType-WriteAttributes\">WriteAttributes</a> in the user pool client to control how attributes can\n                be mutated for new use cases instead of using\n                <code>DeveloperOnlyAttribute</code>.</p>\n         </note>\n         <p>Specifies whether the attribute type is developer only. This attribute can only be\n            modified by an administrator. Users won't be able to modify this attribute using their\n            access token. For example, <code>DeveloperOnlyAttribute</code> can be modified using\n            AdminUpdateUserAttributes but can't be updated using UpdateUserAttributes.</p>"}))
    SchemaAttributeType.add_member(:mutable, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'Mutable', traits: {"smithy.api#default" => nil, "smithy.api#documentation" => "<p>Specifies whether the value of the attribute can be changed.</p>\n         <p>Any user pool attribute whose value you map from an IdP attribute must be mutable,\n            with a parameter value of <code>true</code>. Amazon Cognito updates mapped attributes when users\n            sign in to your application through an IdP. If an attribute is immutable, Amazon Cognito throws\n            an error when it attempts to update the attribute. For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pools-specifying-attribute-mapping.html\">Specifying Identity Provider Attribute Mappings for Your User\n                Pool</a>.</p>"}))
    SchemaAttributeType.add_member(:required, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'Required', traits: {"smithy.api#default" => nil, "smithy.api#documentation" => "<p>Specifies whether a user pool attribute is required. If the attribute is required and\n            the user doesn't provide a value, registration or sign-in will fail.</p>"}))
    SchemaAttributeType.add_member(:number_attribute_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: NumberAttributeConstraintsType, location_name: 'NumberAttributeConstraints', traits: {"smithy.api#documentation" => "<p>Specifies the constraints for an attribute of the number type.</p>"}))
    SchemaAttributeType.add_member(:string_attribute_constraints, Smithy::Schema::Shapes::ShapeRef.new(shape: StringAttributeConstraintsType, location_name: 'StringAttributeConstraints', traits: {"smithy.api#documentation" => "<p>Specifies the constraints for an attribute of the string type.</p>"}))
