    SetRiskConfigurationRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to set a risk configuration. If you include\n                <code>UserPoolId</code> in your request, don't include <code>ClientId</code>.\n            When the client ID is null, the same risk configuration is applied to all the clients in\n            the userPool. When you include both <code>ClientId</code> and <code>UserPoolId</code>,\n            Amazon Cognito maps the configuration to the app client only.</p>", "smithy.api#required" => {}}))
    SetRiskConfigurationRequest.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientIdType, location_name: 'ClientId', traits: {"smithy.api#documentation" => "<p>The ID of the app client where you want to set a risk configuration. If\n                <code>ClientId</code> is null, then the risk configuration is mapped to\n                <code>UserPoolId</code>. When the client ID is null, the same risk configuration is\n            applied to all the clients in the userPool.</p>\n         <p>When you include a <code>ClientId</code> parameter, Amazon Cognito maps the configuration to\n            the app client. When you include both <code>ClientId</code> and <code>UserPoolId</code>,\n            Amazon Cognito maps the configuration to the app client only.</p>"}))
    SetRiskConfigurationRequest.add_member(:compromised_credentials_risk_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CompromisedCredentialsRiskConfigurationType, location_name: 'CompromisedCredentialsRiskConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration of automated reactions to detected compromised credentials. Includes\n            settings for blocking future sign-in requests and for the types of password-submission\n            events you want to monitor.</p>"}))
    SetRiskConfigurationRequest.add_member(:account_takeover_risk_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountTakeoverRiskConfigurationType, location_name: 'AccountTakeoverRiskConfiguration', traits: {"smithy.api#documentation" => "<p>The settings for automated responses and notification templates for adaptive\n            authentication with threat protection.</p>"}))
    SetRiskConfigurationRequest.add_member(:risk_exception_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RiskExceptionConfigurationType, location_name: 'RiskExceptionConfiguration', traits: {"smithy.api#documentation" => "<p>A set of IP-address overrides to threat protection. You can set up IP-address\n            always-block and always-allow lists.</p>"}))
    SetRiskConfigurationRequest.type = Types::SetRiskConfigurationRequest
    SetRiskConfigurationResponse.add_member(:risk_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RiskConfigurationType, location_name: 'RiskConfiguration', traits: {"smithy.api#documentation" => "<p>The API response that contains the risk configuration that you set and the timestamp\n            of the most recent change.</p>", "smithy.api#required" => {}}))
