    SetUICustomizationRequest.add_member(:user_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'UserPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the user pool where you want to apply branding to the classic hosted\n            UI.</p>", "smithy.api#required" => {}}))
    SetUICustomizationRequest.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientIdType, location_name: 'ClientId', traits: {"smithy.api#documentation" => "<p>The ID of the app client that you want to customize. To apply a default style to all\n            app clients not configured with client-level branding, set this parameter value to\n                <code>ALL</code>.</p>"}))
    SetUICustomizationRequest.add_member(:css, Smithy::Schema::Shapes::ShapeRef.new(shape: CSSType, location_name: 'CSS', traits: {"smithy.api#documentation" => "<p>A plaintext CSS file that contains the custom fields that you want to apply to your\n            user pool or app client. To download a template, go to the Amazon Cognito console. Navigate to\n            your user pool <i>App clients</i> tab, select <i>Login\n                pages</i>, edit <i>Hosted UI (classic) style</i>, and select\n            the link to <code>CSS template.css</code>.</p>"}))
    SetUICustomizationRequest.add_member(:image_file, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageFileType, location_name: 'ImageFile', traits: {"smithy.api#documentation" => "<p>The image that you want to set as your login in the classic hosted UI, as a\n            Base64-formatted binary object.</p>"}))
    SetUICustomizationRequest.type = Types::SetUICustomizationRequest
