    SetUICustomizationResponse.type = Types::SetUICustomizationResponse
    SetUserMFAPreferenceRequest.add_member(:sms_mfa_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: SMSMfaSettingsType, location_name: 'SMSMfaSettings', traits: {"smithy.api#documentation" => "<p>User preferences for SMS message MFA. Activates or deactivates SMS MFA and sets it as\n            the preferred MFA method when multiple methods are available.</p>"}))
    SetUserMFAPreferenceRequest.add_member(:software_token_mfa_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: SoftwareTokenMfaSettingsType, location_name: 'SoftwareTokenMfaSettings', traits: {"smithy.api#documentation" => "<p>User preferences for time-based one-time password (TOTP) MFA. Activates or deactivates\n            TOTP MFA and sets it as the preferred MFA method when multiple methods are available.\n            Users must register a TOTP authenticator before they set this as their preferred MFA\n            method.</p>"}))
    SetUserMFAPreferenceRequest.add_member(:email_mfa_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailMfaSettingsType, location_name: 'EmailMfaSettings', traits: {"smithy.api#documentation" => "<p>User preferences for email message MFA. Activates or deactivates email MFA and sets it\n            as the preferred MFA method when multiple methods are available.\n            To activate this setting, your user pool must be in the <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/feature-plans-features-essentials.html\">\n                     Essentials tier</a> or higher.</p>"}))
    SetUserMFAPreferenceRequest.add_member(:access_token, Smithy::Schema::Shapes::ShapeRef.new(shape: TokenModelType, location_name: 'AccessToken', traits: {"smithy.api#documentation" => "<p>A valid access token that Amazon Cognito issued to the currently signed-in user. Must include a scope claim for \n<code>aws.cognito.signin.user.admin</code>.</p>", "smithy.api#required" => {}}))
    SetUserMFAPreferenceRequest.type = Types::SetUserMFAPreferenceRequest
