    SetUserPoolMfaConfigRequest.add_member(:sms_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SmsMfaConfigType, location_name: 'SmsMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Configures user pool SMS messages for MFA. Sets the message template and the SMS\n            message sending configuration for Amazon SNS.</p>"}))
    SetUserPoolMfaConfigRequest.add_member(:software_token_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SoftwareTokenMfaConfigType, location_name: 'SoftwareTokenMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Configures a user pool for time-based one-time password (TOTP) MFA. Enables or\n            disables TOTP.</p>"}))
    SetUserPoolMfaConfigRequest.add_member(:email_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailMfaConfigType, location_name: 'EmailMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Sets configuration for user pool email message MFA and sign-in with one-time passwords\n            (OTPs). Includes the subject and body of the email message template for sign-in and MFA\n            messages. To activate this setting, your user pool must be in the <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/feature-plans-features-essentials.html\">\n                     Essentials tier</a> or higher.</p>"}))
    SetUserPoolMfaConfigRequest.add_member(:mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolMfaType, location_name: 'MfaConfiguration', traits: {"smithy.api#documentation" => "<p>Sets multi-factor authentication (MFA) to be on, off, or optional. When\n                <code>ON</code>, all users must set up MFA before they can sign in. When\n                <code>OPTIONAL</code>, your application must make a client-side determination of\n            whether a user wants to register an MFA device. For user pools with adaptive\n            authentication with threat protection, choose <code>OPTIONAL</code>.</p>\n         <p>When <code>MfaConfiguration</code> is <code>OPTIONAL</code>, managed login\n            doesn't automatically prompt users to set up MFA. Amazon Cognito generates MFA prompts in\n            API responses and in managed login for users who have chosen and configured a preferred\n            MFA factor.</p>"}))
    SetUserPoolMfaConfigRequest.add_member(:web_authn_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAuthnConfigurationType, location_name: 'WebAuthnConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration of your user pool for passkey, or WebAuthn, authentication and\n            registration. You can set this configuration independent of the MFA configuration\n            options in this operation.</p>"}))
    SetUserPoolMfaConfigRequest.type = Types::SetUserPoolMfaConfigRequest
    SetUserPoolMfaConfigResponse.add_member(:sms_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SmsMfaConfigType, location_name: 'SmsMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Shows user pool SMS message configuration for MFA and sign-in with SMS-message OTPs.\n            Includes the message template and the SMS message sending configuration for\n            Amazon SNS.</p>"}))
    SetUserPoolMfaConfigResponse.add_member(:software_token_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SoftwareTokenMfaConfigType, location_name: 'SoftwareTokenMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Shows user pool configuration for time-based one-time password (TOTP) MFA. Includes\n            TOTP enabled or disabled state.</p>"}))
    SetUserPoolMfaConfigResponse.add_member(:email_mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailMfaConfigType, location_name: 'EmailMfaConfiguration', traits: {"smithy.api#documentation" => "<p>Shows configuration for user pool email message MFA and sign-in with one-time\n            passwords (OTPs). Includes the subject and body of the email message template for\n            sign-in and MFA messages. To activate this setting, your user pool must be in the <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/feature-plans-features-essentials.html\">\n                     Essentials tier</a> or higher.</p>"}))
    SetUserPoolMfaConfigResponse.add_member(:mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolMfaType, location_name: 'MfaConfiguration', traits: {"smithy.api#documentation" => "<p>Displays multi-factor authentication (MFA) as on, off, or optional. When\n                <code>ON</code>, all users must set up MFA before they can sign in. When\n                <code>OPTIONAL</code>, your application must make a client-side determination of\n            whether a user wants to register an MFA device. For user pools with adaptive\n            authentication with threat protection, choose <code>OPTIONAL</code>.</p>\n         <p>When <code>MfaConfiguration</code> is <code>OPTIONAL</code>, managed login\n            doesn't automatically prompt users to set up MFA. Amazon Cognito generates MFA prompts in\n            API responses and in managed login for users who have chosen and configured a preferred\n            MFA factor.</p>"}))
    SetUserPoolMfaConfigResponse.add_member(:web_authn_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: WebAuthnConfigurationType, location_name: 'WebAuthnConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration of your user pool for passkey, or WebAuthn, sign-in with\n            authenticators like biometric and security-key devices. Includes relying-party\n            configuration and settings for user-verification requirements.</p>"}))
    SetUserPoolMfaConfigResponse.type = Types::SetUserPoolMfaConfigResponse
    SetUserSettingsRequest.add_member(:access_token, Smithy::Schema::Shapes::ShapeRef.new(shape: TokenModelType, location_name: 'AccessToken', traits: {"smithy.api#documentation" => "<p>A valid access token that Amazon Cognito issued to the currently signed-in user. Must include a scope claim for \n<code>aws.cognito.signin.user.admin</code>.</p>", "smithy.api#required" => {}}))
    SetUserSettingsRequest.add_member(:mfa_options, Smithy::Schema::Shapes::ShapeRef.new(shape: MFAOptionListType, location_name: 'MFAOptions', traits: {"smithy.api#documentation" => "<p>You can use this parameter only to set an SMS configuration that uses SMS for\n            delivery.</p>", "smithy.api#required" => {}}))
