    SignInPolicyType.type = Types::SignInPolicyType
    SignUpRequest.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientIdType, location_name: 'ClientId', traits: {"smithy.api#documentation" => "<p>The ID of the app client where the user wants to sign up.</p>", "smithy.api#required" => {}}))
    SignUpRequest.add_member(:secret_hash, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretHashType, location_name: 'SecretHash', traits: {"smithy.api#documentation" => "<p>A keyed-hash message authentication code (HMAC) calculated using the secret key of a\n            user pool client and username plus the client ID in the message. For more information\n            about <code>SecretHash</code>, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/signing-up-users-in-your-app.html#cognito-user-pools-computing-secret-hash\">Computing secret hash values</a>.</p>"}))
    SignUpRequest.add_member(:username, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameType, location_name: 'Username', traits: {"smithy.api#documentation" => "<p>The username of the user that you want to sign up. The value of this parameter is\n            typically a username, but can be any alias attribute in your user pool.</p>", "smithy.api#required" => {}}))
    SignUpRequest.add_member(:password, Smithy::Schema::Shapes::ShapeRef.new(shape: PasswordType, location_name: 'Password', traits: {"smithy.api#documentation" => "<p>The user's proposed password. The password must comply with the <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/managing-users-passwords.html\">password requirements</a> of your user pool.</p>\n         <p>Users can sign up without a password when your user pool supports passwordless sign-in\n            with email or SMS OTPs. To create a user with no password, omit this parameter or submit\n            a blank value. You can only create a passwordless user when passwordless sign-in is\n            available.</p>"}))
    SignUpRequest.add_member(:user_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeListType, location_name: 'UserAttributes', traits: {"smithy.api#documentation" => "<p>An array of name-value pairs representing user attributes.</p>\n         <p>For custom attributes, include a <code>custom:</code> prefix in the attribute name,\n            for example <code>custom:department</code>.</p>"}))
    SignUpRequest.add_member(:validation_data, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeListType, location_name: 'ValidationData', traits: {"smithy.api#documentation" => "<p>Temporary user attributes that contribute to the outcomes of your pre sign-up Lambda\n    trigger. This set of key-value pairs are for custom validation of information that you \n    collect from your users but don't need to retain.</p>\n         <p>Your Lambda function can analyze this additional data and act on it. Your function\n    can automatically confirm and verify select users or perform external API operations \n    like logging user attributes and validation data to Amazon CloudWatch Logs.</p>\n         <p>For more information about the pre sign-up Lambda trigger, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-lambda-pre-sign-up.html\">Pre sign-up Lambda trigger</a>.</p>"}))
    SignUpRequest.add_member(:analytics_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: AnalyticsMetadataType, location_name: 'AnalyticsMetadata', traits: {"smithy.api#documentation" => "<p>Information that supports analytics outcomes with Amazon Pinpoint, including the \nuser's endpoint ID. The endpoint ID is a destination for Amazon Pinpoint push notifications, for example a device identifier, \nemail address, or phone number.</p>"}))
    SignUpRequest.add_member(:user_context_data, Smithy::Schema::Shapes::ShapeRef.new(shape: UserContextDataType, location_name: 'UserContextData', traits: {"smithy.api#documentation" => "<p>Contextual data about your user session like the device fingerprint, IP address, or location. Amazon Cognito threat \nprotection evaluates the risk of an authentication event based on the context that your app generates and passes to Amazon Cognito\nwhen it makes API requests.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-settings-viewing-threat-protection-app.html\">Collecting data for threat protection in\napplications</a>.</p>"}))
    SignUpRequest.add_member(:client_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientMetadataType, location_name: 'ClientMetadata', traits: {"smithy.api#documentation" => "<p>A map of custom key-value pairs that you can provide as input for any custom workflows\n            that this action triggers.</p>\n         <p>You create custom workflows by assigning Lambda functions to user pool triggers.\n            When you use the SignUp API action, Amazon Cognito invokes any functions that are assigned to the\n            following triggers: <i>pre sign-up</i>, <i>custom\n                message</i>, and <i>post confirmation</i>. When Amazon Cognito invokes\n            any of these functions, it passes a JSON payload, which the function receives as input.\n            This payload contains a <code>clientMetadata</code> attribute, which provides the data\n            that you assigned to the ClientMetadata parameter in your SignUp request. In your\n            function code in Lambda, you can process the <code>clientMetadata</code> value to enhance\n            your workflow for your specific needs.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-identity-pools-working-with-aws-lambda-triggers.html\">\nUsing Lambda triggers</a> in the <i>Amazon Cognito Developer Guide</i>.</p>\n         <note>\n            <p>When you use the <code>ClientMetadata</code> parameter, note that Amazon Cognito won't do the\n                following:</p>\n            <ul>\n               <li>\n                  <p>Store the <code>ClientMetadata</code> value. This data is available only\n                        to Lambda triggers that are assigned to a user pool to support custom\n                        workflows. If your user pool configuration doesn't include triggers, the\n                        <code>ClientMetadata</code> parameter serves no purpose.</p>\n               </li>\n               <li>\n                  <p>Validate the <code>ClientMetadata</code> value.</p>\n               </li>\n               <li>\n                  <p>Encrypt the <code>ClientMetadata</code> value. Don't send sensitive\n                        information in this parameter.</p>\n               </li>\n            </ul>\n         </note>"}))
    SignUpRequest.type = Types::SignUpRequest
    SignUpResponse.add_member(:user_confirmed, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanType, location_name: 'UserConfirmed', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether the user was automatically confirmed. You can auto-confirm users\n            with a <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-lambda-pre-sign-up.html\">pre sign-up Lambda trigger</a>.</p>", "smithy.api#required" => {}}))
    SignUpResponse.add_member(:code_delivery_details, Smithy::Schema::Shapes::ShapeRef.new(shape: CodeDeliveryDetailsType, location_name: 'CodeDeliveryDetails', traits: {"smithy.api#documentation" => "<p>In user pools that automatically verify and confirm new users, Amazon Cognito sends users a\n            message with a code or link that confirms ownership of the phone number or email address\n            that they entered. The <code>CodeDeliveryDetails</code> object is information about the\n            delivery destination for that link or code.</p>"}))
    SignUpResponse.add_member(:user_sub, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'UserSub', traits: {"smithy.api#documentation" => "<p>The unique identifier of the new user, for example\n                <code>a1b2c3d4-5678-90ab-cdef-EXAMPLE11111</code>.</p>", "smithy.api#required" => {}}))
    SignUpResponse.add_member(:session, Smithy::Schema::Shapes::ShapeRef.new(shape: SessionType, location_name: 'Session', traits: {"smithy.api#documentation" => "<p>A session Id that you can pass to <code>ConfirmSignUp</code> when you want to\n            immediately sign in your user with the <code>USER_AUTH</code> flow after they complete\n            sign-up.</p>"}))
    SignUpResponse.type = Types::SignUpResponse
