    UpdateAuthEventFeedbackRequest.add_member(:feedback_token, Smithy::Schema::Shapes::ShapeRef.new(shape: TokenModelType, location_name: 'FeedbackToken', traits: {"smithy.api#documentation" => "<p>The feedback token, an encrypted object generated by Amazon Cognito and passed to your user in\n            the notification email message from the event.</p>", "smithy.api#required" => {}}))
    UpdateAuthEventFeedbackRequest.add_member(:feedback_value, Smithy::Schema::Shapes::ShapeRef.new(shape: FeedbackValueType, location_name: 'FeedbackValue', traits: {"smithy.api#documentation" => "<p>Your feedback to the authentication event. When you provide a <code>FeedbackValue</code>\nvalue of <code>valid</code>, you tell Amazon Cognito that you trust a user session where Amazon Cognito\nhas evaluated some level of risk. When you provide a <code>FeedbackValue</code> value of\n<code>invalid</code>, you tell Amazon Cognito that you don't trust a user session, or you \ndon't believe that Amazon Cognito evaluated a high-enough risk level.</p>", "smithy.api#required" => {}}))
