    UserImportJobType.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was created. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
    UserImportJobType.add_member(:start_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'StartDate', traits: {"smithy.api#documentation" => "<p>The date when the user import job was started.</p>"}))
    UserImportJobType.add_member(:completion_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'CompletionDate', traits: {"smithy.api#documentation" => "<p>The date when the user import job was completed.</p>"}))
    UserImportJobType.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: UserImportJobStatusType, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the user import job. One of the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Created</code> - The job was created but not started.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Pending</code> - A transition state. You have started the job, but it\n                    has not begun importing users yet.</p>\n            </li>\n            <li>\n               <p>\n                  <code>InProgress</code> - The job has started, and users are being\n                    imported.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Stopping</code> - You have stopped the job, but the job has not stopped\n                    importing users yet.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Stopped</code> - You have stopped the job, and the job has stopped\n                    importing users.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Succeeded</code> - The job has completed successfully.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Failed</code> - The job has stopped due to an error.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Expired</code> - You created a job, but did not start the job within\n                    24-48 hours. All data associated with the job was deleted, and the job can't be\n                    started.</p>\n            </li>\n         </ul>"}))
    UserImportJobType.add_member(:cloud_watch_logs_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'CloudWatchLogsRoleArn', traits: {"smithy.api#documentation" => "<p>The role Amazon Resource Name (ARN) for the Amazon CloudWatch Logging role for the user import\n            job. For more information, see \"Creating the CloudWatch Logs IAM Role\" in the Amazon Cognito Developer\n            Guide.</p>"}))
    UserImportJobType.add_member(:imported_users, Smithy::Schema::Shapes::ShapeRef.new(shape: LongType, location_name: 'ImportedUsers', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of users that were successfully imported.</p>"}))
