    UserPoolPolicyType.add_member(:password_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PasswordPolicyType, location_name: 'PasswordPolicy', traits: {"smithy.api#documentation" => "<p>The password policy settings for a user pool, including complexity, history, and\n            length requirements.</p>"}))
    UserPoolPolicyType.add_member(:sign_in_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: SignInPolicyType, location_name: 'SignInPolicy', traits: {"smithy.api#documentation" => "<p>The policy for allowed types of authentication in a user pool.</p>"}))
    UserPoolPolicyType.type = Types::UserPoolPolicyType
