    UserPoolTierType.add_member(:essentials, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ESSENTIALS', traits: {"smithy.api#enumValue" => "ESSENTIALS"}))
