    UserPoolType.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolIdType, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>The ID of the user pool.</p>"}))
    UserPoolType.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolNameType, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the user pool.</p>"}))
    UserPoolType.add_member(:policies, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolPolicyType, location_name: 'Policies', traits: {"smithy.api#documentation" => "<p>A list of user pool policies. Contains the policy that sets password-complexity\n            requirements.</p>"}))
    UserPoolType.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: DeletionProtectionType, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>When active, <code>DeletionProtection</code> prevents accidental deletion of your user\npool. Before you can delete a user pool that you have protected against deletion, you\nmust deactivate this feature.</p>\n         <p>When you try to delete a protected user pool in a <code>DeleteUserPool</code> API request, \nAmazon Cognito returns an <code>InvalidParameterException</code> error. To delete a protected user pool, \nsend a new <code>DeleteUserPool</code> request after you deactivate deletion protection in an \n<code>UpdateUserPool</code> API request.</p>"}))
    UserPoolType.add_member(:lambda_config, Smithy::Schema::Shapes::ShapeRef.new(shape: LambdaConfigType, location_name: 'LambdaConfig', traits: {"smithy.api#documentation" => "<p>A collection of user pool Lambda triggers. Amazon Cognito invokes triggers at several possible\n            stages of user pool operations. Triggers can modify the outcome of the operations that\n            invoked them.</p>"}))
    UserPoolType.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: StatusType, location_name: 'Status', traits: {"smithy.api#deprecated" => {"message" => "This property is no longer available."}, "smithy.api#documentation" => "<p>This parameter is no longer used.</p>"}))
    UserPoolType.add_member(:last_modified_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'LastModifiedDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was modified. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
    UserPoolType.add_member(:creation_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'CreationDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was created. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
    UserPoolType.add_member(:schema_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: SchemaAttributesListType, location_name: 'SchemaAttributes', traits: {"smithy.api#documentation" => "<p>A list of the user attributes and their properties in your user pool. The attribute\n            schema contains standard attributes, custom attributes with a <code>custom:</code>\n            prefix, and developer attributes with a <code>dev:</code> prefix. For more information,\n            see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-settings-attributes.html\">User pool\n                attributes</a>.</p>\n         <p>Developer-only attributes are a legacy feature of user pools, and are read-only to all\n            app clients. You can create and update developer-only attributes only with\n            IAM-authenticated API operations. Use app client read/write permissions instead.</p>"}))
    UserPoolType.add_member(:auto_verified_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: VerifiedAttributesListType, location_name: 'AutoVerifiedAttributes', traits: {"smithy.api#documentation" => "<p>The attributes that are auto-verified in a user pool.</p>"}))
    UserPoolType.add_member(:alias_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: AliasAttributesListType, location_name: 'AliasAttributes', traits: {"smithy.api#documentation" => "<p>Attributes supported as an alias for this user pool. An alias is an attribute that\n            users can enter as an alternative username. Possible values: <b>phone_number</b>, <b>email</b>, or <b>preferred_username</b>.</p>"}))
    UserPoolType.add_member(:username_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameAttributesListType, location_name: 'UsernameAttributes', traits: {"smithy.api#documentation" => "<p>Specifies whether a user can use an email address or phone number as a username when\n            they sign up.</p>"}))
    UserPoolType.add_member(:sms_verification_message, Smithy::Schema::Shapes::ShapeRef.new(shape: SmsVerificationMessageType, location_name: 'SmsVerificationMessage', traits: {"smithy.api#documentation" => "<p>This parameter is no longer used.</p>"}))
    UserPoolType.add_member(:email_verification_message, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailVerificationMessageType, location_name: 'EmailVerificationMessage', traits: {"smithy.api#documentation" => "<p>This parameter is no longer used.</p>"}))
    UserPoolType.add_member(:email_verification_subject, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailVerificationSubjectType, location_name: 'EmailVerificationSubject', traits: {"smithy.api#documentation" => "<p>This parameter is no longer used.</p>"}))
    UserPoolType.add_member(:verification_message_template, Smithy::Schema::Shapes::ShapeRef.new(shape: VerificationMessageTemplateType, location_name: 'VerificationMessageTemplate', traits: {"smithy.api#documentation" => "<p>The template for the verification message that your user pool delivers to users who\n            set an email address or phone number attribute.</p>"}))
    UserPoolType.add_member(:sms_authentication_message, Smithy::Schema::Shapes::ShapeRef.new(shape: SmsVerificationMessageType, location_name: 'SmsAuthenticationMessage', traits: {"smithy.api#documentation" => "<p>The contents of the SMS authentication message.</p>"}))
    UserPoolType.add_member(:user_attribute_update_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: UserAttributeUpdateSettingsType, location_name: 'UserAttributeUpdateSettings', traits: {"smithy.api#documentation" => "<p>The settings for updates to user attributes. These settings include the property <code>AttributesRequireVerificationBeforeUpdate</code>,\na user-pool setting that tells Amazon Cognito how to handle changes to the value of your users' email address and phone number attributes. For\nmore information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/user-pool-settings-email-phone-verification.html#user-pool-settings-verifications-verify-attribute-updates\">\nVerifying updates to email addresses and phone numbers</a>.</p>"}))
    UserPoolType.add_member(:mfa_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolMfaType, location_name: 'MfaConfiguration', traits: {"smithy.api#documentation" => "<p>Can be one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>OFF</code> - MFA tokens aren't required and can't be specified during user\n                    registration.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ON</code> - MFA tokens are required for all user registrations. You can\n                    only specify required when you're initially creating a user pool.</p>\n            </li>\n            <li>\n               <p>\n                  <code>OPTIONAL</code> - Users have the option when registering to create an MFA\n                    token.</p>\n            </li>\n         </ul>"}))
    UserPoolType.add_member(:device_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DeviceConfigurationType, location_name: 'DeviceConfiguration', traits: {"smithy.api#documentation" => "<p>The device-remembering configuration for a user pool. A null value indicates that you\n            have deactivated device remembering in your user pool.</p>\n         <note>\n            <p>When you provide a value for any <code>DeviceConfiguration</code> field, you\n                activate the Amazon Cognito device-remembering feature.</p>\n         </note>"}))
    UserPoolType.add_member(:estimated_number_of_users, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerType, location_name: 'EstimatedNumberOfUsers', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>A number estimating the size of the user pool.</p>"}))
    UserPoolType.add_member(:email_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EmailConfigurationType, location_name: 'EmailConfiguration', traits: {"smithy.api#documentation" => "<p>The email configuration of your user pool. The email configuration type sets your\n            preferred sending method, Amazon Web Services Region, and sender for messages from your user\n            pool.</p>"}))
    UserPoolType.add_member(:sms_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SmsConfigurationType, location_name: 'SmsConfiguration', traits: {"smithy.api#documentation" => "<p>User pool configuration for delivery of SMS messages with Amazon Simple Notification Service. To send SMS\n            messages with Amazon SNS in the Amazon Web Services Region that you want, the Amazon Cognito user pool uses an\n            Identity and Access Management (IAM) role in your Amazon Web Services account.</p>"}))
    UserPoolType.add_member(:user_pool_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolTagsType, location_name: 'UserPoolTags', traits: {"smithy.api#documentation" => "<p>The tags that are assigned to the user pool. A tag is a label that you can apply to\n            user pools to categorize and manage them in different ways, such as by purpose, owner,\n            environment, or other criteria.</p>"}))
    UserPoolType.add_member(:sms_configuration_failure, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'SmsConfigurationFailure', traits: {"smithy.api#documentation" => "<p>The reason why the SMS configuration can't send the messages to your users.</p>\n         <p>This message might include comma-separated values to describe why your SMS\n            configuration can't send messages to user pool end users.</p>\n         <dl>\n            <dt>InvalidSmsRoleAccessPolicyException</dt>\n            <dd>\n               <p>The Identity and Access Management role that Amazon Cognito uses to send SMS messages isn't properly\n                        configured. For more information, see <a href=\"https://docs.aws.amazon.com/cognito-user-identity-pools/latest/APIReference/API_SmsConfigurationType.html\">SmsConfigurationType</a>.</p>\n            </dd>\n            <dt>SNSSandbox</dt>\n            <dd>\n               <p>The Amazon Web Services account is in the SNS SMS Sandbox and messages will\n                        only reach verified end users. This parameter won’t get populated with\n                        SNSSandbox if the user creating the user pool doesn’t have SNS permissions.\n                        To learn how to move your Amazon Web Services account out of the sandbox, see\n                            <a href=\"https://docs.aws.amazon.com/sns/latest/dg/sns-sms-sandbox-moving-to-production.html\">Moving out\n                            of the SMS sandbox</a>.</p>\n            </dd>\n         </dl>"}))
    UserPoolType.add_member(:email_configuration_failure, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'EmailConfigurationFailure', traits: {"smithy.api#documentation" => "<p>Deprecated. Review error codes from API requests with\n                <code>EventSource:cognito-idp.amazonaws.com</code> in CloudTrail for\n            information about problems with user pool email configuration.</p>"}))
    UserPoolType.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: DomainType, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The domain prefix, if the user pool has a domain associated with it.</p>"}))
    UserPoolType.add_member(:custom_domain, Smithy::Schema::Shapes::ShapeRef.new(shape: DomainType, location_name: 'CustomDomain', traits: {"smithy.api#documentation" => "<p>A custom domain name that you provide to Amazon Cognito. This parameter applies only if you use\n            a custom domain to host the sign-up and sign-in pages for your application. An example\n            of a custom domain name might be <code>auth.example.com</code>.</p>\n         <p>For more information about adding a custom domain to your user pool, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pools-add-custom-domain.html\">Using Your Own Domain for the Hosted UI</a>.</p>"}))
    UserPoolType.add_member(:admin_create_user_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AdminCreateUserConfigType, location_name: 'AdminCreateUserConfig', traits: {"smithy.api#documentation" => "<p>The configuration for <code>AdminCreateUser</code> requests.</p>"}))
    UserPoolType.add_member(:user_pool_add_ons, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolAddOnsType, location_name: 'UserPoolAddOns', traits: {"smithy.api#documentation" => "<p>Contains settings for activation of threat protection, including the operating \nmode and additional authentication types. To log user security information but take \nno action, set to <code>AUDIT</code>. To configure automatic security responses to \npotentially unwanted traffic to your user pool, set to <code>ENFORCED</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pool-settings-advanced-security.html\">Adding advanced security to a user pool</a>. To activate this setting, your user pool must be on the <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/feature-plans-features-plus.html\">\n                     Plus tier</a>.</p>"}))
    UserPoolType.add_member(:username_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UsernameConfigurationType, location_name: 'UsernameConfiguration', traits: {"smithy.api#documentation" => "<p>Case sensitivity of the username input for the selected sign-in option. When case\n            sensitivity is set to <code>False</code> (case insensitive), users can sign in with any\n            combination of capital and lowercase letters. For example, <code>username</code>,\n                <code>USERNAME</code>, or <code>UserName</code>, or for email,\n                <code>email@example.com</code> or <code>EMaiL@eXamplE.Com</code>. For most use\n            cases, set case sensitivity to <code>False</code> (case insensitive) as a best practice.\n            When usernames and email addresses are case insensitive, Amazon Cognito treats any variation in\n            case as the same user, and prevents a case variation from being assigned to the same\n            attribute for a different user.</p>"}))
    UserPoolType.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnType, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the user pool.</p>"}))
    UserPoolType.add_member(:account_recovery_setting, Smithy::Schema::Shapes::ShapeRef.new(shape: AccountRecoverySettingType, location_name: 'AccountRecoverySetting', traits: {"smithy.api#documentation" => "<p>The available verified method a user can use to recover their password when they call\n                <code>ForgotPassword</code>. You can use this setting to define a preferred method\n            when a user has more than one method available. With this setting, SMS doesn't qualify\n            for a valid password recovery mechanism if the user also has SMS multi-factor\n            authentication (MFA) activated. In the absence of this setting, Amazon Cognito uses the legacy\n            behavior to determine the recovery method where SMS is preferred through email.</p>"}))
    UserPoolType.add_member(:user_pool_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: UserPoolTierType, location_name: 'UserPoolTier', traits: {"smithy.api#documentation" => "<p>The user pool <a href=\"https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-sign-in-feature-plans.html\">feature plan</a>, or tier. This parameter determines the\n            eligibility of the user pool for features like managed login, access-token\n            customization, and threat protection. Defaults to <code>ESSENTIALS</code>.</p>"}))
