    UserType.add_member(:user_create_date, Smithy::Schema::Shapes::ShapeRef.new(shape: DateType, location_name: 'UserCreateDate', traits: {"smithy.api#documentation" => "<p>The date and time when the item was created. Amazon Cognito returns this timestamp in UNIX epoch time format. Your SDK might render the output in a \nhuman-readable format like ISO 8601 or a Java <code>Date</code> object.</p>"}))
