    WebAuthnConfigurationType.add_member(:user_verification, Smithy::Schema::Shapes::ShapeRef.new(shape: UserVerificationType, location_name: 'UserVerification', traits: {"smithy.api#documentation" => "<p>When <code>required</code>, users can only register and sign in users with passkeys\n            that are capable of <a href=\"https://www.w3.org/TR/webauthn-2/#enum-userVerificationRequirement\">user\n                verification</a>. When <code>preferred</code>, your user pool doesn't\n            require the use of authenticators with user verification but encourages it.</p>"}))
